import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"19、【临】 兑下坤上","description":"周易口诀义 - 19、【临】 兑下坤上","frontmatter":{"title":"19、【临】 兑下坤上","description":"周易口诀义 - 19、【临】 兑下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/021.md","filePath":"zh/classics/koujueyi/021.md"}'),r={name:"zh/classics/koujueyi/021.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_19、【临】-兑下坤上" tabindex="-1">19、【临】 兑下坤上 <a class="header-anchor" href="#_19、【临】-兑下坤上" aria-label="Permalink to “19、【临】 兑下坤上”">​</a></h1><p>彖曰：「临」，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。至于八月有凶，消不久也。</p><p>象曰：泽上有地，「临」。君子以教思无穷，容保民无疆。</p><p>初九：咸临，贞吉。</p><p>象曰：「咸临贞吉」，志行正也。</p><p>九二：咸临，吉，无不利。</p><p>象曰：「咸临吉无不利」，未顺命也。</p><p>六三：甘临，无攸利。既忧之，无咎。</p><p>象曰：「甘临」，位不当也。「既忧之」，咎不长也。</p><p>六四：至临，无咎。</p><p>象曰：「至临无咎」，位当也。</p><p>六五：知临，大君之宜，吉。</p><p>象曰：「大君之宜」，行中之谓也。</p><p>上六：敦临，吉，无咎。</p><p>象曰：「敦临」之吉，志在内也。</p><p>解读</p><p>「临元亨利贞」者，临，大也，以阳气方长，万物皆盛，亦犹王者盛大之德，威临于下，故称「临」也。凡物盛之时，能备四德，故曰「元亨利贞」也。「至于八月有凶」者，夫盛极必衰，自然常理，临为盛大之卦，故以垂戒之。言「凶」者，临卦是建丑之月卦，阳气方长，至及八月，即四阴已长，四阳却退，小人道长，君子道消也，故曰「八月有凶」也。</p><p>象曰：「泽上有地，临」者，是以大临小，以高临下之义也。「君子以教思无穷，容保民无疆」者，凡为君长以临，当须教化思念，无有穷已，又须含容保爱民人，人即归德边境，不计远迩也。</p><p>「初九，咸临，贞吉」者，咸，感也；以阳感应于阴，相感而临，志行其正，故曰「贞吉」也。</p><p>「九二，咸临，吉，无不利」者，以阳应阴，相感而临也。二是刚阳，五是柔阴，若全顺于五，则刚德全损，全与相违，又失感应之道，必须量时进退，如君臣献可替否之义，故得「吉，无不利」。</p><p>六三，甘临，无攸利。「既忧之，无咎」者，以阴居阳，即是越阴柔之道，小人之行也。甘谓言辞甘美，邪佞不正之名也。六三以邪謟之行以临于物，患必生焉，故无施而利，故曰「甘临，无攸利」。若能恒忧其危，改过自新，乃得无咎，故曰「既忧之，无咎」也。</p><p>六四至临无咎者，以阴应阳，不惧刚长，以至极之善而应临于初，乃得「无咎」也。</p><p>六五知临，大君之宜，吉者，以柔处尊，纳刚以礼，不以威武是用，而知临于物，如似「大君之宜」，所以获「吉」也。</p><p>「上六敦临，吉无咎」者，敦，厚也，处坤之极，即是敦厚以为临也。处于上体，志在尊贤，故获「吉」也。</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
